export default async (request, context) => {
  const candidates = [
    { name: 'Trope', archetype: 'partner-to-client nested', teamSize: 2, nestedTenancyFit: 10, secretsBreadthFit: 6, reachability: 8, notes: 'Only candidate with confirmed 3rd-level nesting need (partner acting for client, client has own sub-scope). Strongest single-differentiator match.' },
    { name: 'Fenrock AI', archetype: 'regulated multi-bank ISV-embed', teamSize: null, nestedTenancyFit: 5, secretsBreadthFit: 10, reachability: 5, notes: 'Heaviest arbitrary-API secrets need (core banking, KYC/AML) plus regulated per-bank isolation. Strongest secrets-breadth match; YC-page-only research, reachability unconfirmed.' },
    { name: 'Pollinate', archetype: 'supply-chain ISV-embed', teamSize: null, nestedTenancyFit: 4, secretsBreadthFit: 9, reachability: 5, notes: 'Distinct per-client ERP/logistics credentials, same secrets-breadth shape as Fenrock, less regulatory urgency.' },
    { name: 'Cohesive', archetype: 'blue-collar SMB ISV-embed', teamSize: null, nestedTenancyFit: 3, secretsBreadthFit: 5, reachability: 6, notes: 'Single-level isolation, moderate secrets need (CRM-per-client), smaller-team reachability.' },
    { name: 'Bravi', archetype: 'home-services ISV-embed', teamSize: 2, nestedTenancyFit: 3, secretsBreadthFit: 5, reachability: 8, notes: '2-employee team, high reachability, single-level tenancy only.' },
    { name: 'autarc', archetype: 'installer-business ISV-embed', teamSize: null, nestedTenancyFit: 3, secretsBreadthFit: 5, reachability: 6, notes: 'Same shape as Bravi, team size unconfirmed.' },
    { name: 'Brickanta', archetype: 'construction bid/procurement ISV-embed', teamSize: null, nestedTenancyFit: 3, secretsBreadthFit: 5, reachability: 6, notes: 'Same shape as Bravi/autarc, per-client-engagement isolation only.' }
  ];
  const weights = { nestedTenancyFit: 0.4, secretsBreadthFit: 0.4, reachability: 0.2 };
  const scored = candidates.map((c) => ({
    ...c,
    score: Math.round(
      (c.nestedTenancyFit * weights.nestedTenancyFit +
        c.secretsBreadthFit * weights.secretsBreadthFit +
        c.reachability * weights.reachability) * 10
    ) / 10
  })).sort((a, b) => b.score - a.score);
  return {
    ranked: scored,
    recommendedFirstBatch: scored.slice(0, 3).map((c) => c.name),
    weightsUsed: weights,
    generatedNote: 'Scores are a research-based prioritization heuristic (rec_2Rh6ti differentiator fit + team-size reachability signals from rec_lg5O8L), not interview-confirmed demand.'
  };
};
